  function startWorkbook(ids){const wanted=ids.filter(id=>ownQuestions().some(q=>q.id===id)),valid=wanted.filter(id=>workbookReady(ownQuestions().find(q=>q.id===id)));if(!valid.length){toast(wanted.length?'选中的题目还未识别完整，原图已保留；完成后即可重做。':'先选择需要重做的错题。');return;}if(valid.length<wanted.length)toast(`先练 ${valid.length} 道已准备好的原题，${wanted.length-valid.length} 道待补全的题目仍在练习册中。`);state.workbook={ids:[...new Set(valid)],index:0,results:{}};for(const id of valid){const q=ownQuestions().find(q=>q.id===id);if(q.bankError)state.bankOriginal[id]={answer:'',feedback:null,hint:false,usedHint:false};{const key=q.lessonError?cardKey({scope:'lesson',lesson_id:q.curriculumLesson,index:q.practiceIndex}):cardKey({scope:'original',question_id:q.serverId,index:0}),entry=state.answerCards[key];if(entry){entry.answers={};entry.feedback=null;entry.message='';}}}navigate('workbook');}
