      canSync:()=>!backendSyncing&&window.MathRefresh.safeToRender(refreshContext()),
      fetchVersion:async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch('app-version.js',{cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error('Unavailable');return (await response.text()).match(/^\/\/ Math build: ([a-f0-9]{64})\s*$/)?.[1]||'';}finally{clearTimeout(timer);}},
